import{_ as a,o,c as t,ag as r}from"./chunks/framework.8tqBsFWt.js";const g=JSON.parse('{"title":"Projects and tasks","description":"","frontmatter":{},"headers":[],"relativePath":"guide/projects.md","filePath":"guide/projects.md"}'),n={name:"guide/projects.md"};function s(i,e,p,l,c,d){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="projects-and-tasks" tabindex="-1">Projects and tasks <a class="header-anchor" href="#projects-and-tasks" aria-label="Permalink to &quot;Projects and tasks&quot;">​</a></h1><p>Every hour you log in VERA is attached to a project. Most are also linked to a task — the type of work you did. Understanding how these work makes logging faster and keeps your team&#39;s data accurate.</p><hr><h2 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h2><p>A project is a body of work — a client engagement, an internal initiative, a recurring retainer. Your organisation&#39;s projects are created and configured by an owner or manager in the console.</p><p>When you log time, you choose the project from the <strong>project dropdown</strong> in the Log time modal. Only active projects you can log against appear there, so you pick from a real list rather than typing a name.</p><hr><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><p>Tasks are categories of work within a project — Design, Development, Strategy, Admin, Client Management, and so on. Each project has a specific set of tasks enabled for it, and the <strong>Task dropdown</strong> only offers those.</p><p>If your team has set a default task for your discipline, the modal pre-selects it for the project you chose — you can change it any time. Internal projects (admin, training, and similar) are task-optional, so you can leave the task blank there.</p><hr><h2 id="project-types" tabindex="-1">Project types <a class="header-anchor" href="#project-types" aria-label="Permalink to &quot;Project types&quot;">​</a></h2><p>Your organisation may run different types of projects. As a team member, the type mostly affects how your manager and owner see the financial picture — it doesn&#39;t change how you log time. The types are:</p><p><strong>Retainer</strong> — an ongoing engagement with a set number of hours and a monthly fee. Runs in periods (usually monthly).</p><p><strong>Time &amp; Materials (T&amp;M)</strong> — billed by the hour. Hours logged directly drive the invoice.</p><p><strong>Fixed Price</strong> — a set fee for a defined scope. Revenue is recognised as the work is completed.</p><p><strong>Agile / Sprint</strong> — work delivered in sprints, each with its own scope and value.</p><p><strong>Pro Bono</strong> — client work at no charge.</p><p><strong>Internal</strong> — overhead, training, admin, R&amp;D, and similar non-client work.</p><hr><h2 id="work-plans-envelopes" tabindex="-1">Work plans (envelopes) <a class="header-anchor" href="#work-plans-envelopes" aria-label="Permalink to &quot;Work plans (envelopes)&quot;">​</a></h2><p>Your manager may give you a work plan on a project — an &quot;envelope&quot; of hours for a particular type of work. It&#39;s how planned effort is tracked: allocated vs logged vs remaining.</p><p>Work plans are planning tools, not gates. You can log time to any active project whether or not you have an envelope for it. Managers create and adjust envelopes from the console; if you&#39;re regularly logging to projects that aren&#39;t part of your plan, let your manager know so they can keep your allocations current.</p>',23)])])}const u=a(n,[["render",s]]);export{g as __pageData,u as default};
